import type { ExtensionFactory } from "@earendil-works/pi-coding-agent";

async function scanCodebase(
  cwd: string,
  ctx: { exec: (cmd: string, args: string[]) => Promise<{ stdout: string }> },
): Promise<string> {
  const results: string[] = [];

  // Directory structure
  try {
    const { stdout } = await ctx.exec("find", [
      cwd,
      "-maxdepth",
      "3",
      "-not",
      "-path",
      "*/node_modules/*",
      "-not",
      "-path",
      "*/.git/*",
      "-not",
      "-path",
      "*/dist/*",
      "-not",
      "-path",
      "*/cdk.out/*",
      "-type",
      "f",
    ]);
    const files = stdout.split("\n").filter(Boolean).slice(0, 50);
    results.push(
      `## Project Structure\n\`\`\`text\n${files.join("\n")}\n\`\`\``,
    );
  } catch {
    results.push("## Project Structure\nCould not list files.");
  }

  // Key dependency files
  for (const file of [
    "package.json",
    "requirements.txt",
    "go.mod",
    "Gemfile",
    "pom.xml",
    "Dockerfile",
    "docker-compose.yml",
  ]) {
    try {
      const { stdout } = await ctx.exec("cat", [`${cwd}/${file}`]);
      results.push(`## ${file}\n\`\`\`\n${stdout.trim()}\n\`\`\``);
    } catch {
      // File doesn't exist, skip
    }
  }

  // Source files (first 5 non-test, non-config files)
  try {
    const { stdout } = await ctx.exec("find", [
      cwd,
      "-maxdepth",
      "3",
      "-not",
      "-path",
      "*/node_modules/*",
      "-not",
      "-path",
      "*/.git/*",
      "-not",
      "-path",
      "*/dist/*",
      "-not",
      "-path",
      "*/cdk.out/*",
      "-not",
      "-path",
      "*/test/*",
      "-not",
      "-path",
      "*/tests/*",
      "-not",
      "-path",
      "*/__snapshots__/*",
      "-name",
      "*.ts",
      "-o",
      "-name",
      "*.js",
      "-o",
      "-name",
      "*.py",
      "-o",
      "-name",
      "*.go",
    ]);
    const srcFiles = stdout.split("\n").filter(Boolean).slice(0, 5);
    for (const file of srcFiles) {
      try {
        const { stdout: content } = await ctx.exec("head", ["-50", file]);
        results.push(`## ${file}\n\`\`\`\n${content.trim()}\n\`\`\``);
      } catch {
        // Skip if can't read
      }
    }
  } catch {
    // Skip if find fails
  }

  return results.join("\n\n");
}

export const pawlCommands: ExtensionFactory = (pi) => {
  pi.registerCommand("plan", {
    description: "Analyze codebase and generate AWS infrastructure plan",
    handler: async (args, ctx) => {
      const scanResult = await scanCodebase(ctx.cwd, ctx);
      const prompt = `Generate an AWS infrastructure plan for this project.

${args ? `User notes: ${args}\n\n` : ""}${scanResult}

Create a structured plan at .pawl/plan.md that covers:
1. Application summary (runtime, framework, type)
2. Proposed architecture (services, network, security, observability)
3. Deployment strategy
4. File plan

Wait for my review before generating any code.`;

      await ctx.sendUserMessage(prompt);
    },
  });

  pi.registerCommand("generate", {
    description: "Generate CDK infrastructure code from approved plan",
    handler: async (_args, ctx) => {
      await ctx.sendUserMessage(
        "Read the approved infrastructure plan at .pawl/plan.md and generate the CDK infrastructure code. " +
        "Use @pawl/cdk constructs and @pawl/lambda handlers. " +
        "Write all files to the infra/ directory. " +
        "Include CDK stacks, Lambda handlers, package.json, tsconfig.json, and cdk.json.",
      );
    },
  });

  pi.registerCommand("well-architected", {
    description: "Run AWS Well-Architected Framework review",
    handler: async (_args, _ctx) => {
      // TODO: implement
    },
  });

  pi.registerCommand("deploy", {
    description: "Deploy infrastructure with CDK",
    handler: async (_args, _ctx) => {
      // TODO: implement
    },
  });

  pi.registerCommand("init", {
    description: "Initialize a new pawl project",
    handler: async (_args, _ctx) => {
      // TODO: implement
    },
  });

  pi.registerCommand("cost", {
    description: "Analyze and optimize AWS costs",
    handler: async (_args, _ctx) => {
      // TODO: implement
    },
  });

  pi.registerCommand("simulate", {
    description: "Simulate infrastructure changes",
    handler: async (_args, _ctx) => {
      // TODO: implement
    },
  });
};

import { intro, log, outro, select, spinner, text } from "@clack/prompts";
import { getModels } from "@earendil-works/pi-ai";
import { parseKnownFiles } from "@smithy/shared-ini-file-loader";
import {
	checkBedrockAccess,
	checkCredentials,
	isSSOTokenValid,
	listProfiles,
	ssoLogin,
} from "./src/aws-credentials";
import { startAgent } from "./src/infra-agent";

intro(
	"🐾 pawl — your AI agent for deploying, reviewing & optimizing cloud infrastructure",
);

// 1. Select AWS profile
const profiles = await listProfiles();
const profile = await select({
	message: "Select an AWS profile",
	options: profiles.map((p) => ({ value: p, label: p })),
});
if (typeof profile !== "string") process.exit(0);

// 2. Check credentials validity
const spin = spinner();
spin.start("Checking credentials...");

const allProfiles = await parseKnownFiles({});
const isSSO = !!allProfiles[profile]?.sso_session;
let valid = false;

if (isSSO) {
	valid = await isSSOTokenValid(profile);
} else {
	try {
		await checkCredentials(profile);
		valid = true;
	} catch {
		valid = false;
	}
}

if (valid) {
	spin.stop("Credentials valid ✓");
} else if (isSSO) {
	spin.stop("SSO token expired, logging in...");
	await ssoLogin(profile);
	log.success("SSO login complete");
} else {
	spin.stop("Credentials invalid for non-SSO profile");
	process.exit(1);
}

process.env.AWS_PROFILE = profile;

// 3. Select model — provider → model → scope → region
const allModels = getModels("amazon-bedrock");

// Group models by base name: strip us./eu./global. prefix to find variants
type Scope = "us" | "eu" | "global" | "amazon" | "base";

type ModelEntry = (typeof allModels)[number];
interface ModelGroup {
	baseName: string;
	provider: string;
	variants: Map<Scope, ModelEntry>;
}

const groups = new Map<string, ModelGroup>();
for (const m of allModels) {
	let scope: Scope | null = null;
	let baseId = m.id;
	for (const p of ["us.", "eu.", "global."]) {
		if (m.id.startsWith(p)) {
			scope = p.slice(0, -1) as Scope;
			baseId = m.id.slice(p.length);
			break;
		}
	}
	if (!scope && m.id.startsWith("amazon.")) {
		scope = "amazon";
		baseId = m.id;
	}
	if (!scope) scope = "base";

	const prov = baseId.split(".")[0];
	if (!groups.has(baseId) && prov) {
		groups.set(baseId, {
			baseName: m.name.replace(/ \((US|EU|Global)\)$/, ""),
			provider: prov,
			variants: new Map(),
		});
	}
	const group = groups.get(baseId);
	if (group) group.variants.set(scope, m);
}

// Build provider list
const BACK = Symbol("back");
const providers = [
	...new Set([...groups.values()].map((g) => g.provider)),
].sort();

let provider = "";
let modelChoice = "";
let scope: Scope = "base";

let step: "provider" | "model" | "scope" = "provider";
while (true) {
	if (step === "provider") {
		const p = await select({
			message: "Select provider",
			options: providers.map((p) => ({
				value: p,
				label: p.charAt(0).toUpperCase() + p.slice(1),
			})),
		});
		if (typeof p !== "string") process.exit(0);
		provider = p;
		step = "model";
	} else if (step === "model") {
		const providerModels = [...groups.entries()].filter(
			([, g]) => g.provider === provider,
		);
		const mc = await select<string | symbol>({
			message: "Select model",
			options: [
				{ value: BACK, label: "← Back" },
				...providerModels.map(([baseId, g]) => ({
					value: baseId,
					label: `${g.baseName} — ${[...g.variants.keys()].join(", ")}`,
				})),
			],
		});
		if (typeof mc === "symbol" && mc === BACK) {
			step = "provider";
			continue;
		}
		if (typeof mc !== "string") process.exit(0);
		modelChoice = mc;
		step = "scope";
	} else {
		const group = groups.get(modelChoice);
		if (!group) {
			step = "model";
			continue;
		}
		const scopes = [...group.variants.keys()];
		if (scopes.length === 1 && scopes[0]) {
			scope = scopes[0];
			break;
		}
		const sc = await select<string | symbol>({
			message: "Select scope",
			options: [
				{ value: BACK, label: "← Back" },
				...scopes.map((s) => ({ value: s as string, label: s.toUpperCase() })),
			],
		});
		if (typeof sc === "symbol" && sc === BACK) {
			step = "model";
			continue;
		}
		if (typeof sc !== "string") process.exit(0);
		scope = sc as Scope;
		break;
	}
}

// Pick region
const region = await text({
	message: "AWS region",
	initialValue: allProfiles[profile]?.region || "us-east-1",
	validate: (v) => (!v ? "Region is required" : undefined),
});
if (typeof region !== "string") process.exit(0);
process.env.AWS_REGION = region;

// Patch all base model IDs with region-appropriate inference profile prefix
const regionPrefix = region.startsWith("eu-")
	? "eu."
	: region.startsWith("ap-")
		? "ap."
		: "us.";
for (const m of allModels) {
	if (
		!m.id.startsWith("us.") &&
		!m.id.startsWith("eu.") &&
		!m.id.startsWith("global.")
	) {
		m.id = `${regionPrefix}${m.id}`;
	}
}

const model = groups.get(modelChoice)?.variants.get(scope);
if (!model) {
	log.error("Could not resolve model");
	process.exit(1);
}

// Verify Bedrock access
const b = spinner();
b.start("Checking Bedrock access...");
const hasBedrock = await checkBedrockAccess(profile);
if (hasBedrock) {
	b.stop("Bedrock access confirmed ✓");
} else {
	b.stop("No Bedrock access for this profile/region");
	process.exit(1);
}

outro(
	`Starting — profile: ${profile} | region: ${region} | model: ${model.name} (${model.id})`,
);

// 6. Start pi-coding-agent interactive TUI
await startAgent(
	model,
	`[pawl-cli] Connected — profile: ${profile} | region: ${region} | model: ${model.name}`,
);

import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import type { Api, Model } from "@earendil-works/pi-ai";
import type { Skill } from "@earendil-works/pi-coding-agent";
import {
	AuthStorage,
	type CreateAgentSessionRuntimeFactory,
	createAgentSessionFromServices,
	createAgentSessionRuntime,
	createAgentSessionServices,
	getAgentDir,
	InteractiveMode,
	ModelRegistry,
	SessionManager,
	SettingsManager,
} from "@earendil-works/pi-coding-agent";
import { awsGuard } from "./aws-guard";
import { pawlCommands } from "./commands";

const __dirname = dirname(fileURLToPath(import.meta.url));
const pawlConstructsSkill: Skill = {
	name: "pawl-constructs",
	description:
		"Use @pawl/cdk, @pawl/agentcore, and @pawl/lambda when architecting, generating, or deploying AWS infrastructure. Always prefer pawl abstractions over raw aws-cdk-lib or raw AWS SDK types.",
	filePath: resolve(__dirname, "..", "skills", "pawl-constructs", "SKILL.md"),
	baseDir: resolve(__dirname, "..", "skills"),
	source: "custom",
};
const pawlPlanSkill: Skill = {
	name: "pawl-plan",
	description:
		"Generate AWS infrastructure plans for deploying applications. Analyze codebase first, then produce a structured plan.",
	filePath: resolve(__dirname, "..", "skills", "pawl-plan", "SKILL.md"),
	baseDir: resolve(__dirname, "..", "skills"),
	source: "custom",
};
const pawlCodegenSkill: Skill = {
	name: "pawl-codegen",
	description:
		"Generate AWS CDK infrastructure code and Lambda handlers from an approved infrastructure plan. Always use @pawl/cdk and @pawl/lambda.",
	filePath: resolve(__dirname, "..", "skills", "pawl-codegen", "SKILL.md"),
	baseDir: resolve(__dirname, "..", "skills"),
	source: "custom",
};

export async function startAgent(model: Model<Api>, message: string) {
	const authStorage = AuthStorage.create();
	const modelRegistry = ModelRegistry.create(authStorage);

	const settingsManager = SettingsManager.inMemory({
		enableSkillCommands: false,
	});

	const createRuntime: CreateAgentSessionRuntimeFactory = async ({
		cwd,
		sessionManager,
		sessionStartEvent,
	}) => {
		const services = await createAgentSessionServices({
			cwd,
			authStorage,
			modelRegistry,
			settingsManager,
			resourceLoaderOptions: {
				extensionFactories: [pawlCommands, awsGuard],
				skillsOverride: (current) => ({
					skills: [
						...current.skills,
						pawlConstructsSkill,
						pawlPlanSkill,
						pawlCodegenSkill,
					],
					diagnostics: current.diagnostics,
				}),
			},
		});
		return {
			...(await createAgentSessionFromServices({
				services,
				sessionManager,
				sessionStartEvent,
				model,
			})),
			services,
			diagnostics: services.diagnostics,
		};
	};

	const runtime = await createAgentSessionRuntime(createRuntime, {
		cwd: process.cwd(),
		agentDir: getAgentDir(),
		sessionManager: SessionManager.create(process.cwd()),
	});

	const mode = new InteractiveMode(runtime, { initialMessage: message });
	await mode.run();
}

import { join } from "node:path";
import {
	BedrockClient,
	ListFoundationModelsCommand,
} from "@aws-sdk/client-bedrock";
import {
	CreateTokenCommand,
	type CreateTokenCommandOutput,
	RegisterClientCommand,
	SSOOIDCClient,
	StartDeviceAuthorizationCommand,
} from "@aws-sdk/client-sso-oidc";
import {
	GetCallerIdentityCommand,
	type GetCallerIdentityCommandOutput,
	STSClient,
} from "@aws-sdk/client-sts";
import {
	getSSOTokenFromFile,
	loadSsoSessionData,
	parseKnownFiles,
} from "@smithy/shared-ini-file-loader";
import { $ } from "bun";

export async function listProfiles(): Promise<string[]> {
	const profiles = await parseKnownFiles({});
	return Object.keys(profiles);
}

export async function checkCredentials(
	profile?: string,
): Promise<GetCallerIdentityCommandOutput> {
	const client = new STSClient({ profile });
	return client.send(new GetCallerIdentityCommand({}));
}

export async function isSSOTokenValid(profile: string): Promise<boolean> {
	const profiles = await parseKnownFiles({});
	const ssoSession = profiles[profile]?.sso_session;
	if (!ssoSession) return false;

	try {
		const token = await getSSOTokenFromFile(ssoSession);
		return !!token.expiresAt && new Date(token.expiresAt) > new Date();
	} catch {
		return false;
	}
}

export async function ssoLogin(profile: string): Promise<void> {
	const profiles = await parseKnownFiles({});
	const ssoSessionName = profiles[profile]?.sso_session;
	if (!ssoSessionName)
		throw new Error(`Profile "${profile}" has no sso_session`);

	const sessions = await loadSsoSessionData();
	const session = sessions[ssoSessionName];
	if (!session?.sso_start_url || !session?.sso_region)
		throw new Error(
			`SSO session "${ssoSessionName}" missing sso_start_url or sso_region`,
		);

	const oidc = new SSOOIDCClient({ region: session.sso_region });

	const { clientId, clientSecret } = await oidc.send(
		new RegisterClientCommand({ clientName: "pawl-cli", clientType: "public" }),
	);

	const { verificationUriComplete, deviceCode, interval } = await oidc.send(
		new StartDeviceAuthorizationCommand({
			clientId,
			clientSecret,
			startUrl: session.sso_start_url,
		}),
	);

	console.log(`Opening browser for SSO login:\n${verificationUriComplete}`);
	await $`open ${verificationUriComplete ?? ""}`.quiet();

	const pollMs = (interval ?? 5) * 1000;
	let token: CreateTokenCommandOutput | undefined;
	while (!token) {
		await new Promise((r) => setTimeout(r, pollMs));
		try {
			token = await oidc.send(
				new CreateTokenCommand({
					clientId,
					clientSecret,
					deviceCode,
					grantType: "urn:ietf:params:oauth:grant-type:device_code",
				}),
			);
		} catch (e: unknown) {
			const err = e as { name?: string };
			if (err.name === "AuthorizationPendingException") continue;
			if (err.name === "SlowDownException") {
				await new Promise((r) => setTimeout(r, pollMs));
				continue;
			}
			throw e;
		}
	}

	const home = Bun.env.HOME || "~";
	const cacheDir = join(home, ".aws", "sso", "cache");
	await $`mkdir -p ${cacheDir}`.quiet();
	const cacheKey = new Bun.CryptoHasher("sha1")
		.update(ssoSessionName)
		.digest("hex");
	await Bun.write(
		join(cacheDir, `${cacheKey}.json`),
		JSON.stringify(
			{
				startUrl: session.sso_start_url,
				region: session.sso_region,
				accessToken: token.accessToken,
				expiresAt: new Date(
					Date.now() + (token.expiresIn ?? 28800) * 1000,
				).toISOString(),
			},
			null,
			2,
		),
	);

	console.log(`SSO login successful for profile "${profile}"`);
}

export async function checkBedrockAccess(profile?: string): Promise<boolean> {
	try {
		const client = new BedrockClient({ profile });
		await client.send(
			new ListFoundationModelsCommand({ byOutputModality: "TEXT" }),
		);
		return true;
	} catch {
		return false;
	}
}

