				if (cmd === "find" && args.includes("-maxdepth")) {
					return { stdout: "/pawl/package.json\n/pawl/index.ts" };
				}
				if (cmd === "cat") {
					return { stdout: '{"name":"test","version":"1.0.0"}' };
